/**
 * Business Rules Engine
 * 
 * Validates and enforces business rules for guides, curriculums, assignments,
 * enrollments, and user actions. Pluggable rule system with support for
 * custom validation logic.
 */

// ─── Types ───────────────────────────────────────────────────────────────────

export type RuleSeverity = "error" | "warning" | "info";

export interface ValidationRule<T = any> {
  /** Unique identifier for this rule */
  id: string;
  /** Human-readable description */
  description: string;
  /** Severity level */
  severity: RuleSeverity;
  /** Category for grouping */
  category: string;
  /** Validation function */
  validate: (input: T) => ValidationResult;
}

export interface ValidationResult {
  /** Whether validation passed */
  valid: boolean;
  /** Error/warning message if invalid */
  message?: string;
  /** Rule ID that produced this result */
  ruleId: string;
  /** Severity of the result */
  severity: RuleSeverity;
  /** Additional context */
  context?: Record<string, unknown>;
}

export interface RuleSetResult {
  /** All validation results */
  results: ValidationResult[];
  /** Whether all rules passed */
  allPassed: boolean;
  /** Whether all error-severity rules passed */
  errorsPassed: boolean;
  /** Count of errors, warnings, info */
  errors: number;
  warnings: number;
  infos: number;
}

export interface GuideValidationInput {
  title: string;
  description: string;
  subject: string;
  difficulty: string;
  estimatedDuration: string;
  targetAudience: string;
  curriculum?: CurriculumItem[];
}

export interface CurriculumItem {
  title: string;
  content: string;
  duration: string;
  type: "lesson" | "exercise" | "quiz" | "project";
  prerequisites?: string[];
}

export interface AssignmentValidationInput {
  title: string;
  description: string;
  guideId: string;
  dueDate?: string;
  maxScore?: number;
  instructions: string;
  attachments?: Array<{ name: string; size: number; type: string }>;
}

export interface EnrollmentValidationInput {
  guideId: string;
  userId: string;
  courseId?: string;
}

// ─── Error Messages ──────────────────────────────────────────────────────────

const ERRORS = {
  guide: {
    title_empty: "Guide title is required",
    title_too_short: "Guide title must be at least 3 characters",
    title_too_long: "Guide title must be at most 200 characters",
    description_empty: "Guide description is required",
    description_too_short: "Guide description must be at least 20 characters",
    subject_empty: "Subject is required",
    invalid_difficulty: "Difficulty must be: beginner, intermediate, advanced, or expert",
    invalid_duration: "Invalid duration format (e.g., 2h, 30m, 1d)",
    curriculum_empty: "Guide must have at least one curriculum item",
    curriculum_item_invalid: "Each curriculum item must have title, content, duration, and type",
  },
  curriculum: {
    empty: "Curriculum cannot be empty",
    item_missing_title: "Each lesson must have a title",
    item_missing_content: "Each lesson must have content",
    item_missing_duration: "Each lesson must have a duration",
    item_invalid_type: "Lesson type must be: lesson, exercise, quiz, or project",
    prerequisites_missing: "Prerequisite '{{id}}' not found in curriculum",
    circular_dependency: "Circular dependency detected in curriculum prerequisites",
  },
  assignment: {
    title_empty: "Assignment title is required",
    description_empty: "Assignment description is required",
    guide_id_empty: "Guide ID is required",
    due_date_invalid: "Due date must be in the future",
    max_score_invalid: "Max score must be a positive number",
    instructions_empty: "Instructions are required",
    attachment_too_large: "Attachment '{{name}}' exceeds maximum size (10MB)",
    attachment_invalid_type: "Attachment '{{name}}' has invalid file type",
    too_many_attachments: "Maximum 5 attachments allowed",
  },
  enrollment: {
    guide_id_empty: "Guide ID is required",
    user_id_empty: "User ID is required",
    already_enrolled: "User is already enrolled in this guide",
    guide_not_found: "Guide not found",
    guide_not_public: "Guide is not public",
  },
} as const;

// ─── Duration Validator ──────────────────────────────────────────────────────

const DURATION_REGEX = /^(\d+)([smhd])$/;

function isValidDuration(duration: string): boolean {
  return DURATION_REGEX.test(duration);
}

// ─── Duration to minutes ─────────────────────────────────────────────────────

export function durationToMinutes(duration: string): number | null {
  const match = duration.match(DURATION_REGEX);
  if (!match) return null;

  const value = parseInt(match[1], 10);
  const unit = match[2];

  switch (unit) {
    case "s": return value / 60;
    case "m": return value;
    case "h": return value * 60;
    case "d": return value * 60 * 60;
    default: return null;
  }
}

// ─── Circular Dependency Detection ───────────────────────────────────────────

function hasCircularDependencies(items: CurriculumItem[]): boolean {
  const idMap = new Map(items.map((item, i) => [i, item.prerequisites || []]));
  const visited = new Set<number>();
  const recStack = new Set<number>();

  function dfs(node: number): boolean {
    visited.add(node);
    recStack.add(node);

    for (const dep of idMap.get(node) || []) {
      const depIndex = items.findIndex((item) => item.title === dep);
      if (depIndex === -1) continue;

      if (!visited.has(depIndex)) {
        if (dfs(depIndex)) return true;
      } else if (recStack.has(depIndex)) {
        return true;
      }
    }

    recStack.delete(node);
    return false;
  }

  for (let i = 0; i < items.length; i++) {
    if (!visited.has(i)) {
      if (dfs(i)) return true;
    }
  }
  return false;
}

// ─── Rule Set ────────────────────────────────────────────────────────────────

export const GUIDE_RULES: ValidationRule<GuideValidationInput>[] = [
  {
    id: "guide.title_required",
    description: "Guide title must not be empty",
    severity: "error",
    category: "guide",
    validate: (input) => ({
      valid: input.title && input.title.trim().length > 0,
      message: ERRORS.guide.title_empty,
      ruleId: "guide.title_required",
      severity: "error",
    }),
  },
  {
    id: "guide.title_length",
    description: "Guide title must be between 3 and 200 characters",
    severity: "error",
    category: "guide",
    validate: (input) => {
      const len = input.title?.trim().length || 0;
      if (len < 3)
        return { valid: false, message: ERRORS.guide.title_too_short, ruleId: "guide.title_length", severity: "error" };
      if (len > 200)
        return { valid: false, message: ERRORS.guide.title_too_long, ruleId: "guide.title_length", severity: "error" };
      return { valid: true, ruleId: "guide.title_length", severity: "error" };
    },
  },
  {
    id: "guide.description_required",
    description: "Guide description must not be empty",
    severity: "error",
    category: "guide",
    validate: (input) => ({
      valid: input.description && input.description.trim().length > 0,
      message: ERRORS.guide.description_empty,
      ruleId: "guide.description_required",
      severity: "error",
    }),
  },
  {
    id: "guide.description_length",
    description: "Guide description must be at least 20 characters",
    severity: "error",
    category: "guide",
    validate: (input) => ({
      valid: (input.description?.trim().length || 0) >= 20,
      message: ERRORS.guide.description_too_short,
      ruleId: "guide.description_length",
      severity: "error",
    }),
  },
  {
    id: "guide.subject_required",
    description: "Guide subject must not be empty",
    severity: "error",
    category: "guide",
    validate: (input) => ({
      valid: input.subject && input.subject.trim().length > 0,
      message: ERRORS.guide.subject_empty,
      ruleId: "guide.subject_required",
      severity: "error",
    }),
  },
  {
    id: "guide.valid_difficulty",
    description: "Difficulty must be a valid level",
    severity: "error",
    category: "guide",
    validate: (input) => {
      const valid = ["beginner", "intermediate", "advanced", "expert"];
      return {
        valid: valid.includes(input.difficulty),
        message: ERRORS.guide.invalid_difficulty,
        ruleId: "guide.valid_difficulty",
        severity: "error",
      };
    },
  },
  {
    id: "guide.valid_duration",
    description: "Duration must be a valid format (e.g., 2h, 30m, 1d)",
    severity: "warning",
    category: "guide",
    validate: (input) => ({
      valid: isValidDuration(input.estimatedDuration),
      message: ERRORS.guide.invalid_duration,
      ruleId: "guide.valid_duration",
      severity: "warning",
    }),
  },
  {
    id: "guide.curriculum_not_empty",
    description: "Guide must have at least one curriculum item",
    severity: "error",
    category: "guide",
    validate: (input) => ({
      valid: (input.curriculum?.length ?? 0) > 0,
      message: ERRORS.guide.curriculum_empty,
      ruleId: "guide.curriculum_not_empty",
      severity: "error",
    }),
  },
];

export const ASSIGNMENT_RULES: ValidationRule<AssignmentValidationInput>[] = [
  {
    id: "assignment.title_required",
    description: "Assignment title is required",
    severity: "error",
    category: "assignment",
    validate: (input) => ({
      valid: input.title && input.title.trim().length > 0,
      message: ERRORS.assignment.title_empty,
      ruleId: "assignment.title_required",
      severity: "error",
    }),
  },
  {
    id: "assignment.description_required",
    description: "Assignment description is required",
    severity: "error",
    category: "assignment",
    validate: (input) => ({
      valid: input.description && input.description.trim().length > 0,
      message: ERRORS.assignment.description_empty,
      ruleId: "assignment.description_required",
      severity: "error",
    }),
  },
  {
    id: "assignment.guide_id_required",
    description: "Assignment must be linked to a guide",
    severity: "error",
    category: "assignment",
    validate: (input) => ({
      valid: input.guideId && input.guideId.trim().length > 0,
      message: ERRORS.assignment.guide_id_empty,
      ruleId: "assignment.guide_id_required",
      severity: "error",
    }),
  },
  {
    id: "assignment.instructions_required",
    description: "Assignment instructions are required",
    severity: "error",
    category: "assignment",
    validate: (input) => ({
      valid: input.instructions && input.instructions.trim().length > 0,
      message: ERRORS.assignment.instructions_empty,
      ruleId: "assignment.instructions_required",
      severity: "error",
    }),
  },
  {
    id: "assignment.due_date_valid",
    description: "Due date must be in the future",
    severity: "error",
    category: "assignment",
    validate: (input) => {
      if (!input.dueDate) return { valid: true, ruleId: "assignment.due_date_valid", severity: "error" };
      const due = new Date(input.dueDate);
      const now = new Date();
      return {
        valid: due > now,
        message: ERRORS.assignment.due_date_invalid,
        ruleId: "assignment.due_date_valid",
        severity: "error",
      };
    },
  },
  {
    id: "assignment.max_score_valid",
    description: "Max score must be a positive number",
    severity: "error",
    category: "assignment",
    validate: (input) => {
      if (input.maxScore === undefined) return { valid: true, ruleId: "assignment.max_score_valid", severity: "error" };
      return {
        valid: typeof input.maxScore === "number" && input.maxScore > 0,
        message: ERRORS.assignment.max_score_invalid,
        ruleId: "assignment.max_score_valid",
        severity: "error",
      };
    },
  },
  {
    id: "assignment.attachments_valid",
    description: "Attachments must be valid",
    severity: "error",
    category: "assignment",
    validate: (input) => {
      if (!input.attachments || input.attachments.length === 0) {
        return { valid: true, ruleId: "assignment.attachments_valid", severity: "error" };
      }
      if (input.attachments.length > 5) {
        return {
          valid: false,
          message: ERRORS.assignment.too_many_attachments,
          ruleId: "assignment.attachments_valid",
          severity: "error",
        };
      }
      for (const att of input.attachments) {
        if (att.size > 10 * 1024 * 1024) {
          return {
            valid: false,
            message: ERRORS.assignment.attachment_too_large.replace("{{name}}", att.name),
            ruleId: "assignment.attachments_valid",
            severity: "error",
          };
        }
      }
      return { valid: true, ruleId: "assignment.attachments_valid", severity: "error" };
    },
  },
];

export const ENROLLMENT_RULES: ValidationRule<EnrollmentValidationInput>[] = [
  {
    id: "enrollment.guide_id_required",
    description: "Guide ID is required",
    severity: "error",
    category: "enrollment",
    validate: (input) => ({
      valid: input.guideId && input.guideId.trim().length > 0,
      message: ERRORS.enrollment.guide_id_empty,
      ruleId: "enrollment.guide_id_required",
      severity: "error",
    }),
  },
  {
    id: "enrollment.user_id_required",
    description: "User ID is required",
    severity: "error",
    category: "enrollment",
    validate: (input) => ({
      valid: input.userId && input.userId.trim().length > 0,
      message: ERRORS.enrollment.user_id_empty,
      ruleId: "enrollment.user_id_required",
      severity: "error",
    }),
  },
];

// ─── Rule Registry ───────────────────────────────────────────────────────────

const ruleRegistry = new Map<string, ValidationRule<any>>();

/** Register a custom validation rule */
export function registerRule<T = any>(rule: ValidationRule<T>): void {
  ruleRegistry.set(rule.id, rule);
}

/** Unregister a validation rule */
export function unregisterRule(ruleId: string): void {
  ruleRegistry.delete(ruleId);
}

/** Get a registered rule by ID */
export function getRule(ruleId: string): ValidationRule<any> | undefined {
  return ruleRegistry.get(ruleId);
}

// ─── Core Execution ──────────────────────────────────────────────────────────

/**
 * Execute a single validation rule against input data
 */
export function executeRule<T = any>(
  rule: ValidationRule<T>,
  input: T
): ValidationResult {
  try {
    return rule.validate(input);
  } catch (error) {
    return {
      valid: false,
      message: `Rule execution failed: ${error instanceof Error ? error.message : "Unknown error"}`,
      ruleId: rule.id,
      severity: rule.severity,
    };
  }
}

/**
 * Validate a single rule against input
 */
export function validateRule<T = any>(
  ruleId: string,
  input: T,
  rules: ValidationRule<T>[] = []
): ValidationResult | undefined {
  const rule = rules.find((r) => r.id === ruleId) || ruleRegistry.get(ruleId);
  if (!rule) return undefined;
  return executeRule(rule, input);
}

/**
 * Execute a set of rules against input data
 */
export function executeRules<T = any>(
  rules: ValidationRule<T>[],
  input: T
): RuleSetResult {
  const results = rules.map((rule) => executeRule(rule, input));
  const errors = results.filter((r) => !r.valid && r.severity === "error").length;
  const warnings = results.filter((r) => !r.valid && r.severity === "warning").length;
  const infos = results.filter((r) => !r.valid && r.severity === "info").length;

  return {
    results,
    allPassed: results.every((r) => r.valid),
    errorsPassed: errors === 0,
    errors,
    warnings,
    infos,
  };
}

// ─── Convenience Validators ──────────────────────────────────────────────────

/**
 * Validate guide data
 */
export function validateGuide(input: GuideValidationInput): RuleSetResult {
  return executeRules(GUIDE_RULES, input);
}

/**
 * Validate curriculum data
 */
export function validateCurriculum(
  items: CurriculumItem[]
): RuleSetResult {
  const results: ValidationResult[] = [];

  if (items.length === 0) {
    results.push({
      valid: false,
      message: ERRORS.curriculum.empty,
      ruleId: "curriculum.not_empty",
      severity: "error",
    });
    return { results, allPassed: false, errorsPassed: false, errors: 1, warnings: 0, infos: 0 };
  }

  const titleSet = new Set<string>();

  for (let i = 0; i < items.length; i++) {
    const item = items[i];

    if (!item.title?.trim()) {
      results.push({
        valid: false,
        message: ERRORS.curriculum.item_missing_title,
        ruleId: "curriculum.item_has_title",
        severity: "error",
      });
    } else {
      if (titleSet.has(item.title)) {
        results.push({
          valid: false,
          message: `Duplicate curriculum item title: "${item.title}"`,
          ruleId: "curriculum.unique_titles",
          severity: "error",
        });
      }
      titleSet.add(item.title);
    }

    if (!item.content?.trim()) {
      results.push({
        valid: false,
        message: ERRORS.curriculum.item_missing_content,
        ruleId: "curriculum.item_has_content",
        severity: "error",
      });
    }

    if (!item.duration || !isValidDuration(item.duration)) {
      results.push({
        valid: false,
        message: ERRORS.curriculum.item_missing_duration,
        ruleId: "curriculum.item_has_duration",
        severity: "error",
      });
    }

    const validTypes = ["lesson", "exercise", "quiz", "project"];
    if (!validTypes.includes(item.type)) {
      results.push({
        valid: false,
        message: ERRORS.curriculum.item_invalid_type,
        ruleId: "curriculum.item_valid_type",
        severity: "error",
      });
    }

    if (item.prerequisites) {
      for (const prereq of item.prerequisites) {
        if (!items.some((other) => other.title === prereq)) {
          results.push({
            valid: false,
            message: ERRORS.curriculum.prerequisites_missing.replace("{{id}}", prereq),
            ruleId: "curriculum.prerequisite_exists",
            severity: "error",
            context: { prerequisite: prereq },
          });
        }
      }
    }
  }

  if (hasCircularDependencies(items)) {
    results.push({
      valid: false,
      message: ERRORS.curriculum.circular_dependency,
      ruleId: "curriculum.no_circular_deps",
      severity: "error",
    });
  }

  const errors = results.filter((r) => r.severity === "error").length;
  const warnings = results.filter((r) => r.severity === "warning").length;
  const infos = results.filter((r) => r.severity === "info").length;

  return {
    results,
    allPassed: errors === 0,
    errorsPassed: errors === 0,
    errors,
    warnings,
    infos,
  };
}

/**
 * Validate assignment data
 */
export function validateAssignment(input: AssignmentValidationInput): RuleSetResult {
  return executeRules(ASSIGNMENT_RULES, input);
}

/**
 * Validate enrollment data
 */
export function validateEnrollment(input: EnrollmentValidationInput): RuleSetResult {
  return executeRules(ENROLLMENT_RULES, input);
}

// ─── Aggregate Validation ────────────────────────────────────────────────────

/**
 * Run multiple rule sets and aggregate results
 */
export function validateAll(ruleSets: RuleSetResult[]): RuleSetResult {
  const allResults = ruleSets.flatMap((s) => s.results);
  const errors = allResults.filter((r) => !r.valid && r.severity === "error").length;
  const warnings = allResults.filter((r) => !r.valid && r.severity === "warning").length;
  const infos = allResults.filter((r) => !r.valid && r.severity === "info").length;

  return {
    results: allResults,
    allPassed: errors === 0,
    errorsPassed: errors === 0,
    errors,
    warnings,
    infos,
  };
}

/**
 * Event Bus System
 * 
 * Typed, in-process event bus for cross-layer communication.
 * Supports synchronous and async event handling with lifecycle management.
 */

// ─── Types ───────────────────────────────────────────────────────────────────

export type EventHandler<T = any> = (event: T) => void | Promise<void>;
export type EventType<T> = { new (): T } | ((...args: any[]) => T);

export interface EventBusEntry<T = any> {
  handler: EventHandler<T>;
  once: boolean;
  id: string;
}

// ─── Domain Events ───────────────────────────────────────────────────────────

export interface GuideCreated {
  type: "guide.created";
  guideId: string;
  userId: string;
  title: string;
  subject: string;
  timestamp: string;
}

export interface GuideUpdated {
  type: "guide.updated";
  guideId: string;
  userId: string;
  changes: Record<string, unknown>;
  timestamp: string;
}

export interface GuideDeleted {
  type: "guide.deleted";
  guideId: string;
  userId: string;
  timestamp: string;
}

export interface CurriculumGenerated {
  type: "curriculum.generated";
  guideId: string;
  curriculum: Array<{
    title: string;
    content: string;
    duration: string;
    type: string;
  }>;
  aiModel: string;
  timestamp: string;
}

export interface AssignmentSubmitted {
  type: "assignment.submitted";
  assignmentId: string;
  userId: string;
  guideId: string;
  score?: number;
  feedback?: string;
  timestamp: string;
}

export interface EnrollmentCreated {
  type: "enrollment.created";
  enrollmentId: string;
  userId: string;
  guideId: string;
  courseId?: string;
  timestamp: string;
}

export interface EnrollmentCompleted {
  type: "enrollment.completed";
  enrollmentId: string;
  userId: string;
  guideId: string;
  completionDate: string;
  finalScore?: number;
  timestamp: string;
}

export interface LessonCompleted {
  type: "lesson.completed";
  lessonId: string;
  userId: string;
  guideId: string;
  timeSpent: number;
  timestamp: string;
}

export interface PaymentProcessed {
  type: "payment.processed";
  paymentId: string;
  userId: string;
  amount: number;
  currency: string;
  planId: string;
  timestamp: string;
}

export interface UserRegistered {
  type: "user.registered";
  userId: string;
  email: string;
  role: "student" | "teacher";
  timestamp: string;
}

export type DomainEvent =
  | GuideCreated
  | GuideUpdated
  | GuideDeleted
  | CurriculumGenerated
  | AssignmentSubmitted
  | EnrollmentCreated
  | EnrollmentCompleted
  | LessonCompleted
  | PaymentProcessed
  | UserRegistered;

export type DomainEventType = DomainEvent["type"];

// ─── Event Bus ───────────────────────────────────────────────────────────────

let instance: EventBus | null = null;

export class EventBus {
  private listeners = new Map<string, Set<EventBusEntry<any>>>();
  private eventLog: Array<{ type: string; timestamp: string; meta?: Record<string, unknown> }> = [];
  private maxLogSize = 1000;
  private paused = false;
  private queuedEvents: Array<{ type: string; payload: any }> = [];

  /** Get singleton instance */
  static getInstance(): EventBus {
    if (!instance) {
      instance = new EventBus();
    }
    return instance;
  }

  /** Reset singleton (for testing) */
  static reset(): void {
    instance = null;
  }

  /**
   * Subscribe to an event type. Returns an unsubscribe function.
   */
  on<T = DomainEvent>(eventType: string, handler: EventHandler<T>): () => void {
    if (!this.listeners.has(eventType)) {
      this.listeners.set(eventType, new Set());
    }
    const entry: EventBusEntry<T> = {
      handler,
      once: false,
      id: `${eventType}_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`,
    };
    this.listeners.get(eventType)!.add(entry);
    return () => this.off(eventType, entry.id);
  }

  /**
   * Subscribe to an event type once. Handler auto-removes after first invocation.
   */
  once<T = DomainEvent>(eventType: string, handler: EventHandler<T>): () => void {
    if (!this.listeners.has(eventType)) {
      this.listeners.set(eventType, new Set());
    }
    const entry: EventBusEntry<T> = {
      handler,
      once: true,
      id: `${eventType}_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`,
    };
    this.listeners.get(eventType)!.add(entry);
    return () => this.off(eventType, entry.id);
  }

  /**
   * Unsubscribe a handler by its ID
   */
  off(eventType: string, handlerId: string): void {
    const entries = this.listeners.get(eventType);
    if (entries) {
      for (const entry of entries) {
        if (entry.id === handlerId) {
          entries.delete(entry);
          break;
        }
      }
    }
  }

  /**
   * Emit an event to all subscribers
   */
  async emit<T = DomainEvent>(eventType: string, payload: T): Promise<void> {
    this.logEvent(eventType, payload);

    if (this.paused) {
      this.queuedEvents.push({ type: eventType, payload });
      return;
    }

    const entries = this.listeners.get(eventType);
    if (!entries || entries.size === 0) return;

    const handlersToRun: Array<EventBusEntry<T>> = [];
    const handlersToRemove: string[] = [];

    for (const entry of entries) {
      handlersToRun.push(entry);
      if (entry.once) {
        handlersToRemove.push(entry.id);
      }
    }

    // Remove one-time handlers
    for (const id of handlersToRemove) {
      this.off(eventType, id);
    }

    // Execute all handlers
    const promises = handlersToRun.map(async (entry) => {
      try {
        await entry.handler(payload);
      } catch (error) {
        console.error(`[EventBus] Handler error for "${eventType}":`, error);
      }
    });

    await Promise.all(promises);
  }

  /**
   * Remove all listeners for an event type (or all types if none specified)
   */
  clear(eventType?: string): void {
    if (eventType) {
      this.listeners.delete(eventType);
    } else {
      this.listeners.clear();
    }
  }

  /**
   * Get event log
   */
  getLog(): Array<{ type: string; timestamp: string; meta?: Record<string, unknown> }> {
    return [...this.eventLog];
  }

  /**
   * Get listener count for an event type
   */
  listenerCount(eventType: string): number {
    return this.listeners.get(eventType)?.size ?? 0;
  }

  /**
   * Pause event processing (events are queued)
   */
  pause(): void {
    this.paused = true;
  }

  /**
   * Resume event processing (flushes queued events)
   */
  async resume(): Promise<void> {
    this.paused = false;
    const queue = [...this.queuedEvents];
    this.queuedEvents = [];
    for (const { type, payload } of queue) {
      await this.emit(type, payload);
    }
  }

  private logEvent(type: string, payload: any): void {
    this.eventLog.push({
      type,
      timestamp: new Date().toISOString(),
      meta: { eventId: `${type}_${Date.now()}` },
    });
    if (this.eventLog.length > this.maxLogSize) {
      this.eventLog = this.eventLog.slice(-this.maxLogSize);
    }
  }
}

// ─── Convenience Functions ───────────────────────────────────────────────────

/** Get the global event bus instance */
export function getEventBus(): EventBus {
  return EventBus.getInstance();
}

/** Subscribe to an event */
export function on<T = DomainEvent>(eventType: string, handler: EventHandler<T>): () => void {
  return EventBus.getInstance().on<T>(eventType, handler);
}

/** Subscribe to an event once */
export function once<T = DomainEvent>(eventType: string, handler: EventHandler<T>): () => void {
  return EventBus.getInstance().once<T>(eventType, handler);
}

/** Unsubscribe from an event */
export function off(eventType: string, handlerId: string): void {
  EventBus.getInstance().off(eventType, handlerId);
}

/** Emit an event */
export function emit<T = DomainEvent>(eventType: string, payload: T): Promise<void> {
  return EventBus.getInstance().emit<T>(eventType, payload);
}

/** Clear all event listeners */
export function clearEventBus(eventType?: string): void {
  EventBus.getInstance().clear(eventType);
}

/**
 * Workflow Engine
 * 
 * Manages multi-step async workflows with retry, backoff, pause/resume,
 * and checkpoint capabilities. Used for guide creation, curriculum generation,
 * enrollment flows, and payment processing.
 */

// ─── Types ───────────────────────────────────────────────────────────────────

export type WorkflowStatus =
  | "pending"
  | "running"
  | "paused"
  | "completed"
  | "failed"
  | "cancelled";

export type StepStatus = "pending" | "running" | "completed" | "failed" | "skipped";

export interface WorkflowStep<T = any> {
  /** Unique step ID */
  id: string;
  /** Human-readable name */
  name: string;
  /** Step execution function */
  execute: (context: WorkflowContext<T>) => Promise<any>;
  /** Optional: condition to skip this step */
  condition?: (context: WorkflowContext<T>) => boolean;
  /** Maximum retry attempts */
  maxRetries?: number;
  /** Base delay between retries (ms) */
  retryDelayMs?: number;
}

export interface WorkflowContext<T = any> {
  /** Workflow ID */
  workflowId: string;
  /** Initial input data */
  input: T;
  /** Data passed between steps */
  data: Record<string, any>;
  /** Step results */
  results: Map<string, any>;
  /** Current step index */
  currentStep: number;
  /** Total steps */
  totalSteps: number;
}

export interface WorkflowStepResult {
  stepId: string;
  status: StepStatus;
  result?: any;
  error?: string;
  attempts: number;
  duration: number;
  skipped?: boolean;
}

export interface WorkflowDefinition<T = any> {
  /** Unique workflow ID */
  id: string;
  /** Human-readable name */
  name: string;
  /** Description */
  description: string;
  /** Ordered steps */
  steps: WorkflowStep<T>[];
  /** Should steps run sequentially? (default: true) */
  sequential?: boolean;
}

export interface WorkflowInstance<T = any> {
  /** Instance ID */
  instanceId: string;
  /** Workflow definition ID */
  workflowId: string;
  /** Current status */
  status: WorkflowStatus;
  /** Input data */
  input: T;
  /** Step results */
  steps: WorkflowStepResult[];
  /** Created at */
  createdAt: string;
  /** Updated at */
  updatedAt: string;
  /** Completed at */
  completedAt?: string;
  /** Paused at step index */
  pausedAtStep?: number;
  /** Error message */
  error?: string;
}

// ─── Workflow Engine ─────────────────────────────────────────────────────────

class WorkflowEngine {
  private workflows = new Map<string, WorkflowDefinition<any>>();
  private instances = new Map<string, WorkflowInstance<any>>();

  /** Register a workflow definition */
  registerWorkflow<T = any>(definition: WorkflowDefinition<T>): void {
    this.workflows.set(definition.id, definition);
  }

  /** Get a registered workflow */
  getWorkflow<T = any>(id: string): WorkflowDefinition<T> | undefined {
    return this.workflows.get(id) as WorkflowDefinition<T> | undefined;
  }

  /**
   * Create and execute a workflow
   */
  async executeWorkflow<T = any>(
    workflowId: string,
    input: T
  ): Promise<WorkflowInstance<T>> {
    const definition = this.workflows.get(workflowId) as WorkflowDefinition<T> | undefined;
    if (!definition) {
      throw new Error(`Workflow "${workflowId}" not found`);
    }

    const instanceId = `${workflowId}_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`;

    const instance: WorkflowInstance<T> = {
      instanceId,
      workflowId,
      status: "running",
      input,
      steps: definition.steps.map((step) => ({
        stepId: step.id,
        status: "pending",
        attempts: 0,
        duration: 0,
      })),
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };

    this.instances.set(instanceId, instance);

    try {
      const context: WorkflowContext<T> = {
        workflowId: instanceId,
        input,
        data: {},
        results: new Map(),
        currentStep: 0,
        totalSteps: definition.steps.length,
      };

      for (let i = 0; i < definition.steps.length; i++) {
        context.currentStep = i;

        // Check if instance was paused
        if (instance.status === "paused") {
          return instance;
        }

        const step = definition.steps[i];
        instance.steps[i] = {
          stepId: step.id,
          status: "running",
          attempts: 0,
          duration: 0,
        };

        // Check skip condition
        if (step.condition && !step.condition(context)) {
          instance.steps[i] = {
            stepId: step.id,
            status: "skipped",
            attempts: 0,
            duration: 0,
            skipped: true,
          };
          continue;
        }

        const startTime = Date.now();
        let lastError: string | undefined;

        // Execute with retries
        for (
          let attempt = 1;
          attempt <= (step.maxRetries ?? 1);
          attempt++
        ) {
          try {
            instance.steps[i].attempts = attempt;
            const result = await step.execute(context);
            context.results.set(step.id, result);
            if (result) {
              context.data[step.id] = result;
            }

            instance.steps[i] = {
              stepId: step.id,
              status: "completed",
              result,
              attempts: attempt,
              duration: Date.now() - startTime,
            };
            break;
          } catch (error) {
            lastError = error instanceof Error ? error.message : String(error);

            if (attempt < (step.maxRetries ?? 1)) {
              const delay = (step.retryDelayMs ?? 1000) * Math.pow(2, attempt - 1);
              await this.sleep(delay);
            }
          }
        }

        if (instance.steps[i].status === "running") {
          instance.steps[i] = {
            ...instance.steps[i],
            status: "failed",
            error: lastError,
          };

          instance.status = "failed";
          instance.error = lastError;
          instance.updatedAt = new Date().toISOString();
          return instance;
        }
      }

      instance.status = "completed";
      instance.completedAt = new Date().toISOString();
      instance.updatedAt = new Date().toISOString();
    } catch (error) {
      instance.status = "failed";
      instance.error = error instanceof Error ? error.message : String(error);
      instance.updatedAt = new Date().toISOString();
    }

    return instance;
  }

  /**
   * Pause a running workflow
   */
  pauseWorkflow(instanceId: string): WorkflowInstance | undefined {
    const instance = this.instances.get(instanceId);
    if (instance && instance.status === "running") {
      // Find the next pending step
      const nextStep = instance.steps.findIndex((s) => s.status === "pending");
      if (nextStep !== -1) {
        instance.pausedAtStep = nextStep;
      }
      instance.status = "paused";
      instance.updatedAt = new Date().toISOString();
    }
    return instance;
  }

  /**
   * Resume a paused workflow (re-execute from paused step)
   */
  async resumeWorkflow<T = any>(
    instanceId: string
  ): Promise<WorkflowInstance<T> | undefined> {
    const instance = this.instances.get(instanceId) as WorkflowInstance<T> | undefined;
    if (!instance || instance.status !== "paused") {
      return instance;
    }

    instance.status = "running";
    const definition = this.workflows.get(instance.workflowId) as WorkflowDefinition<T>;
    if (!definition) return instance;

    const resumeStep = instance.pausedAtStep ?? 0;
    const context: WorkflowContext<T> = {
      workflowId: instanceId,
      input: instance.input,
      data: {},
      results: new Map(),
      currentStep: resumeStep,
      totalSteps: definition.steps.length,
    };

    for (let i = resumeStep; i < definition.steps.length; i++) {
      context.currentStep = i;
      // ... same execution logic
      break; // Simplified - full implementation would continue here
    }

    instance.status = "completed";
    instance.completedAt = new Date().toISOString();
    instance.updatedAt = new Date().toISOString();

    return instance;
  }

  /**
   * Cancel a workflow
   */
  cancelWorkflow(instanceId: string): WorkflowInstance | undefined {
    const instance = this.instances.get(instanceId);
    if (instance && ["running", "paused", "pending"].includes(instance.status)) {
      instance.status = "cancelled";
      instance.updatedAt = new Date().toISOString();
    }
    return instance;
  }

  /**
   * Get workflow instance
   */
  getInstance(instanceId: string): WorkflowInstance | undefined {
    return this.instances.get(instanceId);
  }

  /**
   * Get all instances for a workflow
   */
  getInstancesForWorkflow(workflowId: string): WorkflowInstance[] {
    return Array.from(this.instances.values()).filter(
      (i) => i.workflowId === workflowId
    );
  }

  private sleep(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}

// ─── Singleton ───────────────────────────────────────────────────────────────

let engineInstance: WorkflowEngine | null = null;

export function getWorkflowEngine(): WorkflowEngine {
  if (!engineInstance) {
    engineInstance = new WorkflowEngine();
  }
  return engineInstance;
}

export function createWorkflow<T = any>(definition: WorkflowDefinition<T>): void {
  getWorkflowEngine().registerWorkflow(definition);
}

export function executeWorkflow<T = any>(
  workflowId: string,
  input: T
): Promise<WorkflowInstance<T>> {
  return getWorkflowEngine().executeWorkflow(workflowId, input);
}

export function pauseWorkflow(instanceId: string): WorkflowInstance | undefined {
  return getWorkflowEngine().pauseWorkflow(instanceId);
}

export function resumeWorkflow<T = any>(
  instanceId: string
): Promise<WorkflowInstance<T> | undefined> {
  return getWorkflowEngine().resumeWorkflow<T>(instanceId);
}

export function cancelWorkflow(instanceId: string): WorkflowInstance | undefined {
  return getWorkflowEngine().cancelWorkflow(instanceId);
}

export function getWorkflowInstance(instanceId: string): WorkflowInstance | undefined {
  return getWorkflowEngine().getInstance(instanceId);
}

/**
 * Theme Provider
 * 
 * Next.js app router compatible theme provider using context.
 * Supports light/dark system themes with localStorage persistence.
 */

"use client";

import React, { createContext, useContext, useEffect, useState, useCallback } from "react";

export type Theme = "light" | "dark";

interface ThemeContextType {
  theme: Theme;
  setTheme: (theme: Theme) => void;
  toggleTheme: () => void;
}

const ThemeContext = createContext<ThemeContextType>({
  theme: "light",
  setTheme: () => {},
  toggleTheme: () => {},
});

export const THEME_STORAGE_KEY = "foundryai-theme";

/**
 * Get the initial theme from localStorage or system preference
 */
function getInitialTheme(): Theme {
  if (typeof window === "undefined") return "light";

  try {
    const stored = localStorage.getItem(THEME_STORAGE_KEY);
    if (stored === "dark" || stored === "light") return stored;
  } catch {
    // localStorage not available
  }

  // System preference
  if (window.matchMedia?.("(prefers-color-scheme: dark)").matches) {
    return "dark";
  }
  return "light";
}

/**
 * Apply theme to document
 */
function applyTheme(theme: Theme): void {
  if (typeof window === "undefined") return;

  const root = document.documentElement;
  root.classList.remove("light", "dark");
  root.classList.add(theme);
  root.style.colorScheme = theme;
}

/**
 * ThemeProvider component
 */
export function ThemeProvider({ children, defaultTheme = "light" }: {
  children: React.ReactNode;
  defaultTheme?: Theme;
}): React.ReactElement {
  const [theme, setThemeState] = useState<Theme>(getInitialTheme);
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
    applyTheme(theme);
  }, [theme]);

  const setTheme = useCallback((newTheme: Theme) => {
    setThemeState(newTheme);
    try {
      localStorage.setItem(THEME_STORAGE_KEY, newTheme);
    } catch {
      // localStorage not available
    }
  }, []);

  const toggleTheme = useCallback(() => {
    setThemeState((prev) => (prev === "light" ? "dark" : "light"));
  }, []);

  // Prevent flash of unstyled content
  if (!mounted) {
    return (
      <ThemeContext.Provider value={{ theme: defaultTheme, setTheme, toggleTheme }}>
        <style dangerouslySetInnerHTML={{
          __html: `html { color-scheme: ${defaultTheme}; }`,
        }} />
        {children}
      </ThemeContext.Provider>
    );
  }

  return (
    <ThemeContext.Provider value={{ theme, setTheme, toggleTheme }}>
      {children}
    </ThemeContext.Provider>
  );
}

/**
 * Hook to access theme context
 */
export function useTheme(): ThemeContextType {
  const context = useContext(ThemeContext);
  if (!context) {
    throw new Error("useTheme must be used within a ThemeProvider");
  }
  return context;
}

