/**
 * Supabase Client - Browser
 * 
 * Creates a Supabase client for browser-side operations.
 */

import { createBrowserClient } from "@supabase/ssr";
import { DATABASE_URL } from "@/lib/constants";
import { ANON_KEY } from "@/lib/constants";

export function createSupabaseClient() {
  return createBrowserClient(DATABASE_URL, ANON_KEY);
}

/**
 * Supabase Client - Server
 * 
 * Creates a Supabase client for server-side operations.
 */

import { createServerClient } from "@supabase/ssr";
import { cookies } from "next/headers";
import { DATABASE_URL } from "@/lib/constants";
import { ANON_KEY } from "@/lib/constants";

export async function createSupabaseServerClient(cookieStore: Awaited<ReturnType<typeof cookies>>) {
  return createServerClient(DATABASE_URL, ANON_KEY, {
    cookies: {
      getAll() {
        return cookieStore.getAll();
      },
      setAll(cookiesToSet) {
        try {
          for (const { name, value, options } of cookiesToSet) {
            cookieStore.set(name, value, options);
          }
        } catch {
          // The `setAll` method was called from a Server Component.
          // This can be ignored if you have middleware refreshing
          // user sessions.
        }
      },
    },
  });
}

/**
 * Supabase Client - Middleware
 * 
 * Creates a Supabase client for middleware operations.
 */

import { createServerClient } from "@supabase/ssr";
import { NextResponse, type NextRequest } from "next/server";
import { DATABASE_URL } from "@/lib/constants";
import { ANON_KEY } from "@/lib/constants";

export function createSupabaseMiddlewareClient(request: NextRequest) {
  let supabaseResponse = NextResponse.next({
    request,
  });

  return {
    supabase: createServerClient(DATABASE_URL, ANON_KEY, {
      cookies: {
        getAll() {
          return request.cookies.getAll();
        },
        setAll(cookiesToSet) {
          for (const { name, value, options } of cookiesToSet) {
            request.cookies.set(name, value);
            supabaseResponse = NextResponse.next({
              request,
            });
            supabaseResponse.cookies.set(name, value, options);
          }
        },
      },
    }),
    response: supabaseResponse,
  };
}

/**
 * Project Constants
 * 
 * Centralized configuration values for the FoundryAI project.
 */

export const DATABASE_URL = process.env.NEXT_PUBLIC_SUPABASE_URL || "";
