/**
 * Middleware
 * 
 * Handles authentication, redirects, and feature gating.
 */

import { createSupabaseMiddlewareClient } from "@/lib/supabase/middleware";
import { type NextRequest } from "next/server";

// Paths that don't require authentication
const PUBLIC_PATHS = [
  "/",
  "/sign-in",
  "/sign-up",
  "/magic-link",
  "/forgot-password",
  "/landing",
  "/api/webhooks/stripe",
];

// Paths that require authentication
const PROTECTED_PATHS = [
  "/teacher",
  "/student",
];

// Paths that redirect authenticated users away
const AUTH_REDIRECT_PATHS = [
  "/sign-in",
  "/sign-up",
];

export async function middleware(request: NextRequest) {
  const { supabase, response } = createSupabaseMiddlewareClient(request);

  // Refresh session if expired
  const {
    data: { session },
  } = await supabase.auth.getSession();

  const { pathname } = request.nextUrl;

  // Check if this is a public path
  const isPublic = PUBLIC_PATHS.some((p) => pathname.startsWith(p));

  // Check if this is a protected path
  const isProtected = PROTECTED_PATHS.some((p) => pathname.startsWith(p));

  // Check if this is an auth redirect path
  const isAuthRedirect = AUTH_REDIRECT_PATHS.some((p) => pathname.startsWith(p));

  // Redirect authenticated users away from auth pages
  if (session && isAuthRedirect) {
    // Check role and redirect to appropriate dashboard
    const { data: profile } = await supabase
      .from("user_profiles")
      .select("role")
      .eq("id", session.user.id)
      .single();

    const redirectPath = profile?.role === "teacher"
      ? "/teacher/dashboard"
      : "/student/dashboard";

    return Response.redirect(new URL(redirectPath, request.url));
  }

  // Redirect unauthenticated users to sign-in
  if (!session && isProtected) {
    return Response.redirect(new URL("/sign-in", request.url));
  }

  return response;
}

export const config = {
  matcher: [
    /*
     * Match all request paths except:
     * - _next/static (static files)
     * - _next/image (image optimization files)
     * - favicon.ico (favicon file)
     * - images (public images)
     * - api (API routes) - except webhooks
     */
    "/((?!_next/static|_next/image|favicon.ico|images|api/webhooks).*)",
  ],
};

/**
 * Feature Gate
 * 
 * Provides a simple feature flag system for toggling features
 * based on environment variables and user plan.
 */

import { FEATURES, STRIPE_PLANS } from "./constants";

export type FeatureName = keyof typeof FEATURES;
export type PlanName = keyof typeof STRIPE_PLANS;

interface FeatureContext {
  plan?: PlanName;
}

/**
 * Check if a feature is enabled globally
 */
export function isFeatureEnabled(feature: FeatureName): boolean {
  return !!FEATURES[feature];
}

/**
 * Check if a feature is enabled for a specific plan
 */
export function isFeatureEnabledForPlan(
  feature: FeatureName,
  plan: PlanName
): boolean {
  if (!isFeatureEnabled(feature)) return false;

  // Plan-specific restrictions
  const enterpriseOnly: FeatureName[] = ["teamCollaboration", "liveSessions"];
  const proOrEnterprise: FeatureName[] = ["certificates", "aiCurriculumBuilder"];

  if (enterpriseOnly.includes(feature) && plan !== "enterprise") return false;
  if (proOrEnterprise.includes(feature) && plan === "free") return false;

  return true;
}

/**
 * Feature gate hook
 */
export function useFeatureGate(context: FeatureContext = {}) {
  const canAccess = (feature: FeatureName): boolean => {
    if (!isFeatureEnabled(feature)) return false;
    if (context.plan) {
      return isFeatureEnabledForPlan(feature, context.plan);
    }
    return true;
  };

  return { canAccess };
}

/**
 * AI Curriculum Generation
 * 
 * Generates curriculum content using OpenAI API based on guide parameters.
 */

import { OPENAI_API_KEY, OPENAI_MODEL } from "./constants";

interface CurriculumParams {
  title: string;
  subject: string;
  difficulty: "beginner" | "intermediate" | "advanced" | "expert";
  estimatedDuration: string;
  targetAudience: string;
  description: string;
  numberOfLessons?: number;
}

interface CurriculumLesson {
  id: string;
  title: string;
  content: string;
  duration: string;
  type: "lesson" | "exercise" | "quiz" | "project";
  prerequisites?: string[];
}

export async function generateCurriculum(
  params: CurriculumParams
): Promise<CurriculumLesson[]> {
  if (!OPENAI_API_KEY) {
    throw new Error("OpenAI API key is not configured");
  }

  const {
    title,
    subject,
    difficulty,
    estimatedDuration,
    targetAudience,
    description,
    numberOfLessons = 5,
  } = params;

  const prompt = `
    You are an expert curriculum designer. Create a comprehensive curriculum based on the following parameters.

    Guide Title: ${title}
    Subject: ${subject}
    Difficulty Level: ${difficulty}
    Estimated Total Duration: ${estimatedDuration}
    Target Audience: ${targetAudience}
    Description: ${description}
    Number of Lessons: ${numberOfLessons}

    Generate ${numberOfLessons} lessons that progress logically from basic to advanced concepts.
    Each lesson should include:
    - A clear, descriptive title
    - Detailed content explaining the concepts
    - An estimated duration (format: Xm, Xh, or Xd)
    - Type (lesson, exercise, quiz, or project)
    - Prerequisites (references to other lesson titles, if any)

    Return the response as a JSON array with the following structure:
    [
      {
        "id": "lesson-1",
        "title": "Lesson Title",
        "content": "Detailed lesson content...",
        "duration": "30m",
        "type": "lesson",
        "prerequisites": []
      }
    ]

    Ensure the curriculum is:
    1. Well-structured and progressive
    2. Appropriate for the target difficulty level
    3. Balanced between theory and practice
    4. Includes assessments (quizzes) at appropriate intervals
    5. Ends with a practical project
  `;

  try {
    const response = await fetch("https://api.openai.com/v1/chat/completions", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${OPENAI_API_KEY}`,
      },
      body: JSON.stringify({
        model: OPENAI_MODEL,
        messages: [
          {
            role: "system",
            content:
              "You are an expert curriculum designer who creates structured, progressive learning paths.",
          },
          { role: "user", content: prompt },
        ],
        temperature: 0.7,
        max_tokens: 4000,
      }),
    });

    if (!response.ok) {
      const error = await response.text();
      throw new Error(`OpenAI API error: ${error}`);
    }

    const data = await response.json();
    const content = data.choices[0].message.content;

    // Parse the JSON response
    const curriculum = JSON.parse(content) as CurriculumLesson[];

    // Assign IDs if not present
    return curriculum.map((lesson, index) => ({
      ...lesson,
      id: lesson.id || `lesson-${index + 1}`,
    }));
  } catch (error) {
    console.error("Error generating curriculum:", error);
    throw new Error(
      error instanceof Error
        ? error.message
        : "Failed to generate curriculum"
    );
  }
}

/**
 * Generate AI-powered assignment suggestions
 */
export async function generateAssignmentSuggestions({
  guideTitle,
  subject,
  difficulty,
  lessonCount,
}: {
  guideTitle: string;
  subject: string;
  difficulty: string;
  lessonCount: number;
}): Promise<
  Array<{
    title: string;
    description: string;
    instructions: string;
    maxScore: number;
    dueAfter: string;
  }>
> {
  if (!OPENAI_API_KEY) {
    throw new Error("OpenAI API key is not configured");
  }

  const prompt = `
    Generate ${Math.ceil(lessonCount / 2)} assignments for a "${guideTitle}" course.
    Subject: ${subject}, Difficulty: ${difficulty}

    Each assignment should test practical skills learned in the lessons.
    Return as JSON array with: title, description, instructions, maxScore (0-100), dueAfter (duration format like 2d)
  `;

  const response = await fetch("https://api.openai.com/v1/chat/completions", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${OPENAI_API_KEY}`,
    },
    body: JSON.stringify({
      model: OPENAI_MODEL,
      messages: [
        {
          role: "system",
          content:
            "You are an expert assignment designer for educational courses.",
        },
        { role: "user", content: prompt },
      ],
      temperature: 0.7,
      max_tokens: 2000,
    }),
  });

  if (!response.ok) throw new Error("Failed to generate assignments");

  const data = await response.json();
  return JSON.parse(data.choices[0].message.content);
}

/**
 * Generate quiz questions for a lesson
 */
export async function generateQuizQuestions({
  lessonTitle,
  content,
  difficulty,
  questionCount = 5,
}: {
  lessonTitle: string;
  content: string;
  difficulty: string;
  questionCount?: number;
}): Promise<
  Array<{
    question: string;
    options: string[];
    correctAnswer: number;
    explanation: string;
  }>
> {
  if (!OPENAI_API_KEY) {
    throw new Error("OpenAI API key is not configured");
  }

  const prompt = `
    Generate ${questionCount} multiple-choice quiz questions for the lesson: "${lessonTitle}"
    Difficulty: ${difficulty}
    Content: ${content.substring(0, 1000)}...

    Return as JSON array with: question, options (array of 4 strings), correctAnswer (index 0-3), explanation
  `;

  const response = await fetch("https://api.openai.com/v1/chat/completions", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${OPENAI_API_KEY}`,
    },
    body: JSON.stringify({
      model: OPENAI_MODEL,
      messages: [
        {
          role: "system",
          content: "You are an expert quiz question writer.",
        },
        { role: "user", content: prompt },
      ],
      temperature: 0.7,
      max_tokens: 2000,
    }),
  });

  if (!response.ok) throw new Error("Failed to generate quiz questions");

  const data = await response.json();
  return JSON.parse(data.choices[0].message.content);
}

/**
 * Curriculum Utilities
 * 
 * Helper functions for working with curriculum data.
 */

export interface CurriculumItem {
  id: string;
  title: string;
  content: string;
  duration: string;
  type: "lesson" | "exercise" | "quiz" | "project";
  prerequisites?: string[];
  completed?: boolean;
}

export interface CurriculumStats {
  totalLessons: number;
  completedLessons: number;
  completionPercentage: number;
  totalDuration: string;
  remainingDuration: string;
  lessonsByType: Record<string, number>;
}

/**
 * Parse duration string to minutes
 */
export function parseDurationToMinutes(duration: string): number {
  const match = duration.match(/^(\d+)([smhd])$/);
  if (!match) return 0;

  const value = parseInt(match[1], 10);
  const unit = match[2];

  switch (unit) {
    case "s": return value / 60;
    case "m": return value;
    case "h": return value * 60;
    case "d": return value * 60 * 60;
    default: return 0;
  }
}

/**
 * Calculate curriculum statistics
 */
export function calculateCurriculumStats(curriculum: CurriculumItem[]): CurriculumStats {
  const totalLessons = curriculum.length;
  const completedLessons = curriculum.filter((l) => l.completed).length;
  const completionPercentage =
    totalLessons > 0 ? Math.round((completedLessons / totalLessons) * 100) : 0;

  const totalMinutes = curriculum.reduce(
    (sum, lesson) => sum + parseDurationToMinutes(lesson.duration),
    0
  );
  const remainingMinutes = curriculum
    .filter((l) => !l.completed)
    .reduce((sum, lesson) => sum + parseDurationToMinutes(lesson.duration), 0);

  const lessonsByType = curriculum.reduce(
    (acc, lesson) => {
      acc[lesson.type] = (acc[lesson.type] || 0) + 1;
      return acc;
    },
    {} as Record<string, number>
  );

  return {
    totalLessons,
    completedLessons,
    completionPercentage,
    totalDuration: minutesToDuration(totalMinutes),
    remainingDuration: minutesToDuration(remainingMinutes),
    lessonsByType,
  };
}

/**
 * Convert minutes to duration string
 */
export function minutesToDuration(minutes: number): string {
  if (minutes === 0) return "0m";

  if (minutes >= 1440) {
    const days = Math.floor(minutes / 1440);
    const remainingMins = Math.round(minutes % 1440);
    return remainingMins > 0 ? `${days}d ${remainingMins}m` : `${days}d`;
  }

  if (minutes >= 60) {
    const hours = Math.floor(minutes / 60);
    const remainingMins = Math.round(minutes % 60);
    return remainingMins > 0 ? `${hours}h ${remainingMins}m` : `${hours}h`;
  }

  return `${Math.round(minutes)}m`;
}

/**
 * Get lessons that can be unlocked (prerequisites met)
 */
export function getUnlockedLessons(curriculum: CurriculumItem[]): CurriculumItem[] {
  const completedTitles = new Set(
    curriculum.filter((l) => l.completed).map((l) => l.title)
  );

  return curriculum.filter((lesson) => {
    if (!lesson.prerequisites || lesson.prerequisites.length === 0) {
      return true;
    }
    return lesson.prerequisites.every((prereq) => completedTitles.has(prereq));
  });
}

/**
 * Order lessons by prerequisites (topological sort)
 */
export function orderCurriculum(curriculum: CurriculumItem[]): CurriculumItem[] {
  const ordered: CurriculumItem[] = [];
  const visited = new Set<string>();

  function visit(lesson: CurriculumItem): void {
    if (visited.has(lesson.id)) return;
    visited.add(lesson.id);

    // Visit prerequisites first
    for (const prereq of lesson.prerequisites || []) {
      const prereqLesson = curriculum.find((l) => l.title === prereq);
      if (prereqLesson) {
        visit(prereqLesson);
      }
    }

    ordered.push(lesson);
  }

  for (const lesson of curriculum) {
    visit(lesson);
  }

  return ordered;
}

/**
 * Flatten curriculum content for rendering
 */
export function flattenCurriculum(
  curriculum: CurriculumItem[]
): Array<{ type: string; id: string; title: string; content: string; duration: string }> {
  return curriculum.map((item) => ({
    type: item.type,
    id: item.id,
    title: item.title,
    content: item.content,
    duration: item.duration,
  }));
}

