/**
 * Sidebar Navigation
 *
 * Collapsible sidebar with role-aware navigation.
 * Supports teacher and student roles with different nav items.
 */

"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { useState } from "react";

export interface NavItem {
  label: string;
  href: string;
}

const TEACHER_NAV: NavItem[] = [
  { label: "Dashboard", href: "/teacher/dashboard" },
  { label: "Guides", href: "/teacher/guides" },
  { label: "Courses", href: "/teacher/courses" },
  { label: "Settings", href: "/teacher/settings" },
];

const STUDENT_NAV: NavItem[] = [
  { label: "Dashboard", href: "/student/dashboard" },
  { label: "My Guides", href: "/student/guides" },
  { label: "Assignments", href: "/student/assignments" },
  { label: "Courses", href: "/student/courses" },
  { label: "Analytics", href: "/student/analytics" },
];

export interface SidebarProps {
  role: "teacher" | "student";
}

export function Sidebar({ role }: SidebarProps) {
  const pathname = usePathname();
  const [collapsed, setCollapsed] = useState(false);
  const navItems = role === "teacher" ? TEACHER_NAV : STUDENT_NAV;

  return (
    <aside
      className={`fixed left-0 top-0 z-40 flex h-screen flex-col border-r bg-background transition-all duration-300 ${
        collapsed ? "w-16" : "w-64"
      }`}
    >
      {/* Logo */}
      <div className="flex items-center justify-between border-b p-4">
        {!collapsed && (
          <Link href="/" className="text-xl font-bold text-foreground">
            FoundryAI
          </Link>
        )}
        <button
          onClick={() => setCollapsed(!collapsed)}
          className="flex h-8 w-8 items-center justify-center rounded-lg text-sm text-muted-foreground hover:bg-accent hover:text-accent-foreground"
          aria-label={collapsed ? "Expand sidebar" : "Collapse sidebar"}
        >
          {collapsed ? "→" : "←"}
        </button>
      </div>

      {/* Navigation */}
      <nav className="flex-1 space-y-1 p-2">
        {navItems.map((item) => {
          const isActive = pathname === item.href;
          return (
            <Link
              key={item.href}
              href={item.href}
              className={`flex items-center rounded-lg px-3 py-2.5 text-sm font-medium transition-colors ${
                isActive
                  ? "bg-accent text-accent-foreground"
                  : "text-muted-foreground hover:bg-accent hover:text-accent-foreground"
              }`}
              title={collapsed ? item.label : undefined}
            >
              {!collapsed && <span>{item.label}</span>}
            </Link>
          );
        })}
      </nav>

      {/* Footer */}
      {!collapsed && (
        <div className="border-t p-4 text-xs text-muted-foreground">
          FoundryAI v1.0.0
        </div>
      )}
    </aside>
  );
}

/**
 * Guide Card
 *
 * Displays guide information with badges and enrollment count.
 */

import { Card, CardContent, CardFooter, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import Link from "next/link";

export interface GuideCardProps {
  title: string;
  subject: string;
  difficulty: string;
  estimatedDuration: string;
  enrolledCount: number;
  onEnroll?: () => void;
  guideId?: string;
}

const DIFFICULTY_COLORS: Record<string, string> = {
  beginner: "bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200",
  intermediate: "bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200",
  advanced: "bg-orange-100 text-orange-800 dark:bg-orange-900 dark:text-orange-200",
  expert: "bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200",
};

export function GuideCard({
  title,
  subject,
  difficulty,
  estimatedDuration,
  enrolledCount,
  onEnroll,
  guideId,
}: GuideCardProps) {
  return (
    <Card className="flex flex-col">
      <CardHeader className="pb-2">
        <CardTitle className="text-lg line-clamp-1">{title}</CardTitle>
        <div className="mt-2 flex flex-wrap gap-2">
          <Badge variant="secondary">{subject}</Badge>
          <Badge className={DIFFICULTY_COLORS[difficulty] || ""}>
            {difficulty}
          </Badge>
        </div>
      </CardHeader>
      <CardContent className="flex-1">
        <div className="flex items-center gap-4 text-sm text-muted-foreground">
          <span>⏱ {estimatedDuration}</span>
          <span>👥 {enrolledCount} enrolled</span>
        </div>
      </CardContent>
      <CardFooter className="flex gap-2">
        {guideId && (
          <Button variant="outline" size="sm" asChild>
            <Link href={onEnroll ? `/student/guides/${guideId}` : `/teacher/guides/${guideId}`}>
              View
            </Link>
          </Button>
        )}
        {onEnroll && (
          <Button size="sm" onClick={onEnroll}>
            Enroll
          </Button>
        )}
      </CardFooter>
    </Card>
  );
}

/**
 * Course Card
 *
 * Displays course information with progress bar and enrollment count.
 */

import { Card, CardContent, CardFooter, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Button } from "@/components/ui/button";
import Link from "next/link";

export interface CourseCardProps {
  title: string;
  progress: number;
  enrolledCount: number;
  status: string;
  courseId?: string;
}

const STATUS_COLORS: Record<string, string> = {
  active: "bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200",
  draft: "bg-gray-100 text-gray-800 dark:bg-gray-800 dark:text-gray-200",
  completed: "bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200",
  archived: "bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200",
};

export function CourseCard({
  title,
  progress,
  enrolledCount,
  status,
  courseId,
}: CourseCardProps) {
  return (
    <Card className="flex flex-col">
      <CardHeader className="pb-2">
        <CardTitle className="text-lg line-clamp-1">{title}</CardTitle>
      </CardHeader>
      <CardContent className="flex-1 space-y-3">
        <Progress value={progress} className="h-2" />
        <div className="flex items-center justify-between text-sm text-muted-foreground">
          <span>{progress}% complete</span>
          <span>👥 {enrolledCount} enrolled</span>
        </div>
      </CardContent>
      <CardFooter className="flex items-center justify-between">
        <Badge className={STATUS_COLORS[status] || ""}>{status}</Badge>
        {courseId && (
          <Button variant="ghost" size="sm" asChild>
            <Link href={`/teacher/courses/${courseId}`}>View</Link>
          </Button>
        )}
      </CardFooter>
    </Card>
  );
}

/**
 * Progress Ring
 *
 * SVG circular progress indicator.
 */

interface ProgressRingProps {
  size?: number;
  percentage: number;
  strokeWidth?: number;
}

export function ProgressRing({
  size = 48,
  percentage,
  strokeWidth = 4,
}: ProgressRingProps) {
  const radius = (size - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  const clampedPercentage = Math.min(100, Math.max(0, percentage));
  const strokeDashoffset = circumference * (1 - clampedPercentage / 100);

  return (
    <svg width={size} height={size} className="transform -rotate-90">
      {/* Background circle */}
      <circle
        cx={size / 2}
        cy={size / 2}
        r={radius}
        stroke="hsl(var(--muted))"
        strokeWidth={strokeWidth}
        fill="none"
      />
      {/* Progress circle */}
      <circle
        cx={size / 2}
        cy={size / 2}
        r={radius}
        stroke="hsl(var(--primary))"
        strokeWidth={strokeWidth}
        fill="none"
        strokeLinecap="round"
        strokeDasharray={circumference}
        strokeDashoffset={strokeDashoffset}
        className="transition-all duration-500"
      />
      {/* Percentage text */}
      <text
        x="50%"
        y="50%"
        className="fill-foreground"
        fontSize={size * 0.25}
        fontWeight="bold"
        textAnchor="middle"
        dominantBaseline="central"
        transform={`rotate(90, ${size / 2}, ${size / 2})`}
      >
        {Math.round(clampedPercentage)}%
      </text>
    </svg>
  );
}

/**
 * Empty State
 *
 * Displays when no data is available with optional CTA.
 */

import Link from "next/link";
import { Button } from "@/components/ui/button";

interface EmptyStateProps {
  title?: string;
  description?: string;
  actionLabel?: string;
  actionHref?: string;
}

export function EmptyState({
  title = "No results found",
  description = "Try adjusting your search or filters",
  actionLabel,
  actionHref,
}: EmptyStateProps) {
  return (
    <div className="flex flex-col items-center justify-center py-16 text-center">
      {/* Search icon */}
      <svg
        xmlns="http://www.w3.org/2000/svg"
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        strokeWidth={1.5}
        className="mb-4 h-12 w-12 text-muted-foreground/50"
      >
        <circle cx="11" cy="11" r="8" />
        <path d="m21 21-4.3-4.3" />
      </svg>
      <h3 className="text-lg font-semibold text-foreground">{title}</h3>
      <p className="mt-1 max-w-sm text-sm text-muted-foreground">
        {description}
      </p>
      {actionLabel && actionHref && (
        <Button asChild className="mt-4">
          <Link href={actionHref}>{actionLabel}</Link>
        </Button>
      )}
    </div>
  );
}

/**
 * Loading Skeletons
 *
 * Skeleton placeholders for cards, lists, and tables.
 */

import { Card, CardContent, CardHeader } from "@/components/ui/card";

/** Skeleton for a card */
export function SkeletonCard() {
  return (
    <Card>
      <CardHeader>
        <div className="h-6 w-3/4 animate-pulse rounded bg-muted/50" />
      </CardHeader>
      <CardContent>
        <div className="space-y-3">
          <div className="h-4 w-full animate-pulse rounded bg-muted/50" />
          <div className="h-4 w-5/6 animate-pulse rounded bg-muted/50" />
          <div className="flex gap-2 pt-2">
            <div className="h-6 w-16 animate-pulse rounded-full bg-muted/50" />
            <div className="h-6 w-16 animate-pulse rounded-full bg-muted/50" />
          </div>
        </div>
