          <div className="h-4 flex-1 animate-pulse rounded bg-muted/50" />
          <div className="h-6 w-16 animate-pulse rounded-full bg-muted/50" />
          <div className="h-4 w-12 animate-pulse rounded bg-muted/50" />
        </div>
      ))}
