/**
 * Business Rules Engine Tests
 *
 * Tests for validateGuide, validateCurriculum, validateAssignment.
 */

import {
  validateGuide,
  validateCurriculum,
  validateAssignment,
} from "@/lib/business-rules-engine";

describe("Business Rules Engine", () => {
  describe("validateGuide", () => {
    it("should reject empty guide", () => {
      const result = validateGuide({
        title: "",
        description: "",
        subject: "",
        difficulty: "",
        estimatedDuration: "",
        targetAudience: "",
      });
      expect(result.errors).toBeGreaterThan(0);
      expect(result.allPassed).toBe(false);
    });

    it("should accept valid guide", () => {
      const result = validateGuide({
        title: "Test Guide",
        description: "A test guide description for testing purposes",
        subject: "Math",
        difficulty: "beginner",
        estimatedDuration: "2h",
        targetAudience: "students",
        curriculum: [
          {
            title: "Lesson 1",
            content: "Content here",
            duration: "30m",
            type: "lesson",
          },
        ],
      });
      expect(result.errors).toBe(0);
      expect(result.allPassed).toBe(true);
    });

    it("should reject short title", () => {
      const result = validateGuide({
        title: "AB",
        description: "A test guide description for testing purposes",
        subject: "Math",
        difficulty: "beginner",
        estimatedDuration: "2h",
        targetAudience: "students",
        curriculum: [
          {
            title: "Lesson 1",
            content: "Content",
            duration: "30m",
            type: "lesson",
          },
        ],
      });
      expect(result.errors).toBeGreaterThan(0);
    });
  });

  describe("validateCurriculum", () => {
    it("should reject empty curriculum", () => {
      const result = validateCurriculum([]);
      expect(result.errors).toBeGreaterThan(0);
    });

    it("should reject curriculum with circular dependencies", () => {
      const result = validateCurriculum([
        {
          title: "A",
          content: "x",
          duration: "30m",
          type: "lesson",
          prerequisites: ["B"],
        },
        {
          title: "B",
          content: "x",
          duration: "30m",
          type: "lesson",
          prerequisites: ["A"],
        },
      ]);
      expect(result.errors).toBeGreaterThan(0);
    });

    it("should accept valid curriculum", () => {
      const result = validateCurriculum([
        {
          title: "Lesson 1",
          content: "Content",
          duration: "30m",
          type: "lesson",
        },
        {
          title: "Lesson 2",
          content: "Content",
          duration: "45m",
          type: "exercise",
        },
      ]);
      expect(result.errors).toBe(0);
    });

    it("should reject missing title", () => {
      const result = validateCurriculum([
        {
          title: "",
          content: "Content",
          duration: "30m",
          type: "lesson",
        },
      ]);
      expect(result.errors).toBeGreaterThan(0);
    });
  });

  describe("validateAssignment", () => {
    it("should reject empty assignment", () => {
      const result = validateAssignment({
        title: "",
        description: "",
        guideId: "",
        instructions: "",
      });
      expect(result.errors).toBeGreaterThan(0);
    });

    it("should accept valid assignment", () => {
      const futureDate = new Date(Date.now() + 86400000).toISOString();
      const result = validateAssignment({
        title: "Homework 1",
        description: "Complete the exercises",
        guideId: "guide-123",
        instructions: "Do the following tasks...",
        dueDate: futureDate,
        maxScore: 100,
      });
      expect(result.errors).toBe(0);
    });
  });
});

/**
 * Event Bus Tests
 *
 * Tests for emit, on, once.
 */

import { EventBus } from "@/lib/event-bus";

describe("Event Bus", () => {
  afterEach(() => {
    EventBus.reset();
  });

  it("emit triggers handler", async () => {
    const bus = EventBus.getInstance();
    const handler = jest.fn();
    bus.on("test.event", handler);
    await bus.emit("test.event", { data: "test" });
    expect(handler).toHaveBeenCalledWith({ data: "test" });
  });

  it("once runs handler once", async () => {
    const bus = EventBus.getInstance();
    const handler = jest.fn();
    bus.once("test.event", handler);
    await bus.emit("test.event", {});
    await bus.emit("test.event", {});
    expect(handler).toHaveBeenCalledTimes(1);
  });

  it("on runs handler multiple times", async () => {
    const bus = EventBus.getInstance();
    const handler = jest.fn();
    bus.on("test.event", handler);
    await bus.emit("test.event", {});
    await bus.emit("test.event", {});
    await bus.emit("test.event", {});
    expect(handler).toHaveBeenCalledTimes(3);
  });

  it("off removes handler", async () => {
    const bus = EventBus.getInstance();
    const handler = jest.fn();
    const unsubscribe = bus.on("test.event", handler);
    unsubscribe();
    await bus.emit("test.event", {});
    expect(handler).not.toHaveBeenCalled();
  });

  it("clear removes all handlers", async () => {
    const bus = EventBus.getInstance();
    const handler = jest.fn();
    bus.on("test.event", handler);
    bus.clear();
    await bus.emit("test.event", {});
    expect(handler).not.toHaveBeenCalled();
  });
});

/**
 * Workflow Engine Tests
 *
 * Tests for createWorkflow, executeWorkflow.
 */

import {
  createWorkflow,
  executeWorkflow,
  getWorkflowEngine,
} from "@/lib/workflow-engine";

describe("Workflow Engine", () => {
  beforeEach(() => {
    const engine = getWorkflowEngine();
    // Register a test workflow
    (engine as any).workflows = new Map();
  });

  it("executes steps in order", async () => {
    createWorkflow({
      id: "test-workflow",
      name: "Test",
      description: "Test workflow",
      steps: [
        {
          id: "step1",
          name: "Step 1",
          execute: async () => "result1",
          maxRetries: 1,
          retryDelayMs: 10,
        },
        {
          id: "step2",
          name: "Step 2",
          execute: async () => "result2",
          maxRetries: 1,
          retryDelayMs: 10,
        },
      ],
    });

    const result = await executeWorkflow("test-workflow", {});
    expect(result.status).toBe("completed");
    expect(result.steps[0].status).toBe("completed");
    expect(result.steps[1].status).toBe("completed");
  });

  it("failed step stops workflow", async () => {
    createWorkflow({
      id: "failing-workflow",
      name: "Failing",
      description: "Workflow that fails",
      steps: [
        {
          id: "step1",
          name: "Step 1",
          execute: async () => {
            throw new Error("Step 1 failed");
          },
          maxRetries: 1,
          retryDelayMs: 10,
        },
        {
          id: "step2",
          name: "Step 2",
          execute: async () => "should not run",
          maxRetries: 1,
          retryDelayMs: 10,
        },
      ],
    });

    const result = await executeWorkflow("failing-workflow", {});
    expect(result.status).toBe("failed");
    expect(result.steps[0].status).toBe("failed");
    expect(result.steps[1].status).toBe("pending");
  });

  it("condition can skip steps", async () => {
    createWorkflow({
      id: "conditional-workflow",
      name: "Conditional",
      description: "Workflow with conditions",
      steps: [
        {
          id: "step1",
          name: "Step 1",
          execute: async () => "ran",
          maxRetries: 1,
          retryDelayMs: 10,
        },
        {
          id: "step2",
          name: "Step 2",
          execute: async () => "should not run",
          condition: () => false,
          maxRetries: 1,
          retryDelayMs: 10,
        },
      ],
    });

    const result = await executeWorkflow("conditional-workflow", {});
    expect(result.status).toBe("completed");
    expect(result.steps[0].status).toBe("completed");
    expect(result.steps[1].status).toBe("skipped");
  });
});
